toolScript:
(() => {
  const BUTTON_CONFIG = [
    { idx: 0, label: 'A / Cross' },
    { idx: 1, label: 'B / Circle' },
    { idx: 2, label: 'X / Square' },
    { idx: 3, label: 'Y / Triangle' },
    { idx: 4, label: 'LB / L1' },
    { idx: 5, label: 'RB / R1' },
    { idx: 8, label: 'View / Share' },
    { idx: 9, label: 'Menu / Options' },
    { idx: 10, label: 'LS Click (L3)' },
    { idx: 11, label: 'RS Click (R3)' },
    { idx: 12, label: 'D-Pad Up' },
    { idx: 13, label: 'D-Pad Down' },
    { idx: 14, label: 'D-Pad Left' },
    { idx: 15, label: 'D-Pad Right' },
    { idx: 16, label: 'Guide / Home' },
  ];

  const padStatusDot = document.getElementById('pad-status-dot');
  const padNameEl = document.getElementById('pad-name');
  const padPollingEl = document.getElementById('pad-polling');
  const matrixEl = document.getElementById('buttons-matrix');
  const valLt = document.getElementById('val-lt');
  const barLt = document.getElementById('bar-lt');
  const valRt = document.getElementById('val-rt');
  const barRt = document.getElementById('bar-rt');

  const canvasLs = document.getElementById('canvas-ls');
  const ctxLs = canvasLs?.getContext('2d');
  const canvasRs = document.getElementById('canvas-rs');
  const ctxRs = canvasRs?.getContext('2d');
  const valLsX = document.getElementById('val-ls-x');
  const valLsY = document.getElementById('val-ls-y');
  const valRsX = document.getElementById('val-rs-x');
  const valRsY = document.getElementById('val-rs-y');

  // Render button pills
  BUTTON_CONFIG.forEach((btn) => {
    const pill = document.createElement('div');
    pill.id = 'btn-pill-' + btn.idx;
    pill.className = 'p-2.5 rounded-xl border border-slate-200 bg-slate-50 font-medium text-slate-600 flex items-center justify-between transition-colors';
    pill.innerHTML = `<span>${btn.label}</span><span class="w-2 h-2 rounded-full bg-slate-300 btn-indicator"></span>`;
    matrixEl.appendChild(pill);
  });

  let lastPollTime = performance.now();
  let pollCount = 0;
  let activePadIndex = null;

  function drawRadar(ctx, x, y) {
    if (!ctx) return;
    const w = 140;
    const h = 140;
    const cx = w / 2;
    const cy = h / 2;
    const r = w / 2 - 10;

    ctx.clearRect(0, 0, w, h);

    // Outer border
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.arc(cx, cy, r, 0, Math.PI * 2);
    ctx.stroke();

    // Center crosshairs
    ctx.strokeStyle = '#f1f5f9';
    ctx.beginPath();
    ctx.moveTo(cx, cy - r);
    ctx.lineTo(cx, cy + r);
    ctx.moveTo(cx - r, cy);
    ctx.lineTo(cx + r, cy);
    ctx.stroke();

    // Deadzone circle (8% radius)
    ctx.strokeStyle = '#cbd5e1';
    ctx.setLineDash([2, 2]);
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.08, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    // Stick position
    const px = cx + Math.max(-1, Math.min(1, x)) * r;
    const py = cy + Math.max(-1, Math.min(1, y)) * r;

    ctx.fillStyle = '#4f46e5';
    ctx.beginPath();
    ctx.arc(px, py, 6, 0, Math.PI * 2);
    ctx.fill();
  }

  function poll() {
    const pads = navigator.getGamepads ? navigator.getGamepads() : [];
    let pad = null;
    for (let i = 0; i < pads.length; i++) {
      if (pads[i]) { pad = pads[i]; activePadIndex = i; break; }
    }

    if (pad) {
      padStatusDot.className = 'w-3 h-3 rounded-full bg-emerald-500 animate-pulse';
      padNameEl.textContent = pad.id || 'Connected Gamepad';

      // Measure polling
      pollCount++;
      const now = performance.now();
      if (now - lastPollTime >= 1000) {
        const hz = Math.round((pollCount * 1000) / (now - lastPollTime));
        padPollingEl.textContent = hz + ' Hz';
        pollCount = 0;
        lastPollTime = now;
      }

      // Triggers (Buttons 6 and 7)
      const ltVal = pad.buttons[6] ? pad.buttons[6].value : 0;
      const rtVal = pad.buttons[7] ? pad.buttons[7].value : 0;
      valLt.textContent = ltVal.toFixed(2);
      barLt.style.width = (ltVal * 100).toFixed(0) + '%';
      valRt.textContent = rtVal.toFixed(2);
      barRt.style.width = (rtVal * 100).toFixed(0) + '%';

      // Buttons
      BUTTON_CONFIG.forEach((cfg) => {
        const b = pad.buttons[cfg.idx];
        const pill = document.getElementById('btn-pill-' + cfg.idx);
        if (pill) {
          const indicator = pill.querySelector('.btn-indicator');
          if (b && b.pressed) {
            pill.className = 'p-2.5 rounded-xl border border-indigo-300 bg-indigo-50 font-bold text-indigo-900 flex items-center justify-between transition-colors shadow-xs';
            if (indicator) indicator.className = 'w-2 h-2 rounded-full bg-indigo-600 btn-indicator';
          } else {
            pill.className = 'p-2.5 rounded-xl border border-slate-200 bg-slate-50 font-medium text-slate-600 flex items-center justify-between transition-colors';
            if (indicator) indicator.className = 'w-2 h-2 rounded-full bg-slate-300 btn-indicator';
          }
        }
      });

      // Sticks (Axes 0, 1 for Left Stick, 2, 3 for Right Stick)
      const lsX = pad.axes[0] || 0;
      const lsY = pad.axes[1] || 0;
      const rsX = pad.axes[2] || 0;
      const rsY = pad.axes[3] || 0;

      valLsX.textContent = lsX.toFixed(3);
      valLsY.textContent = lsY.toFixed(3);
      valRsX.textContent = rsX.toFixed(3);
      valRsY.textContent = rsY.toFixed(3);

      drawRadar(ctxLs, lsX, lsY);
      drawRadar(ctxRs, rsX, rsY);
    } else {
      padStatusDot.className = 'w-3 h-3 rounded-full bg-slate-400';
      drawRadar(ctxLs, 0, 0);
      drawRadar(ctxRs, 0, 0);
    }

    requestAnimationFrame(poll);
  }

  window.addEventListener('gamepadconnected', (e) => {
    padStatusDot.className = 'w-3 h-3 rounded-full bg-emerald-500';
    padNameEl.textContent = e.gamepad.id;
  });

  window.addEventListener('gamepaddisconnected', () => {
    padStatusDot.className = 'w-3 h-3 rounded-full bg-slate-400';
    padNameEl.textContent = 'Gamepad disconnected. Connect a controller and press any button.';
  });

  drawRadar(ctxLs, 0, 0);
  drawRadar(ctxRs, 0, 0);
  requestAnimationFrame(poll);
})();
